#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <random>
using namespace std;

int main(){
double x=0,z=0,u=0,lambda=0.8,rho=1.0;
for(int step=0;step<100;step++){
    x=(3+rho*(z-u))/(1+rho);
    double provisional=x+u;
    z=provisional>lambda/rho?provisional-lambda/rho:
        (provisional< -lambda/rho?provisional+lambda/rho:0);
    u+=x-z;
    if(step%20==0)cout<<step<<" "<<x<<" "<<z<<" "<<fabs(x-z)<<endl;
}
if(fabs(x-z)>1e-6)return 1;
    return 0;
}

