#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <random>
using namespace std;

int main(){
vector<double> feature={1,2,3,4,5,6},target={1,1.2,2,4,4.5,5};
for(double threshold:{2.5,3.5,4.5}){
    double leftSum=0,rightSum=0;int leftCount=0,rightCount=0;
    for(int i=0;i<int(feature.size());i++){
        if(feature[i]<=threshold){leftSum+=target[i];leftCount++;}
        else{rightSum+=target[i];rightCount++;}
    }
    double leftMean=leftSum/leftCount,rightMean=rightSum/rightCount,error=0;
    for(int i=0;i<int(feature.size());i++){
        double estimate=feature[i]<=threshold?leftMean:rightMean;
        error+=pow(target[i]-estimate,2);
    }
    cout<<threshold<<" "<<error<<endl;
}
    return 0;
}

