#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <random>
using namespace std;

int main(){
vector<vector<double>> train={{1,2},{2,1},{3,3},{4,2}};
vector<double> trainY={2,2.5,5,5};
vector<vector<double>> valid={{5,1},{6,2}};
vector<double> validY={5.5,7.0};
int bestFeature=-1;double bestLoss=1e100;
for(int feature=0;feature<2;feature++){
    double xx=0,xy=0;
    for(int i=0;i<int(train.size());i++){
        xx+=train[i][feature]*train[i][feature];
        xy+=train[i][feature]*trainY[i];
    }
    if(xx<=0)continue;
    double beta=xy/xx,loss=0;
    for(int i=0;i<int(valid.size());i++)
        loss+=pow(beta*valid[i][feature]-validY[i],2)/valid.size();
    cout<<feature<<" "<<loss<<endl;
    if(loss<bestLoss){bestLoss=loss;bestFeature=feature;}
}
cout<<"Selected feature "<<bestFeature<<endl;
    return 0;
}

