#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <random>
using namespace std;

int main(){
vector<double> trainX={1,2,3,4},trainY={2,4,6,8};
vector<double> validX={5,6},validY={10,12};
double weight=0,rate=0.01,best=1e100,bestWeight=weight;
for(int epoch=0;epoch<180;epoch++){
    double gradient=0;
    for(int i=0;i<int(trainX.size());i++)
        gradient+=2*(weight*trainX[i]-trainY[i])*trainX[i]/trainX.size();
    weight-=rate*gradient;
    double validLoss=0;
    for(int i=0;i<int(validX.size());i++)
        validLoss+=pow(weight*validX[i]-validY[i],2)/validX.size();
    if(validLoss<best){best=validLoss;bestWeight=weight;}
}
cout<<"Best validation weight "<<bestWeight<<" loss "<<best<<endl;
    return 0;
}

