int main(){
double chosenFeature=2,rejectedFeature=0.5,weight=0.2,learningRate=0.1;
for(int step=0;step<30;step++){
    double difference=weight*(chosenFeature-rejectedFeature);
    double probability=1/(1+exp(-difference));
    double loss=-log(probability);
    double gradient=-(1-probability)*(chosenFeature-rejectedFeature);
    weight-=learningRate*gradient;
    if(step%5==0)cout<<step<<" "<<loss<<" "<<weight<<endl;
}
    return 0;
}

