#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <random>
using namespace std;

int main(){
vector<double> observation={1,0.8,1.3,1.4};
double mean=0,variance=1,phi=0.9,process=0.1,noise=0.2;
for(double y:observation){
    double predictedMean=phi*mean;
    double predictedVariance=phi*phi*variance+process;
    double gain=predictedVariance/(predictedVariance+noise);
    mean=predictedMean+gain*(y-predictedMean);
    variance=(1-gain)*predictedVariance;
    cout<<"Kalman gain "<<gain<<" filtered state "<<mean
        <<" variance "<<variance<<endl;
}
    return 0;
}

