#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <random>
using namespace std;

int main(){
double averageDailyValue=20000000;
double volatility=0.02,impactCoefficient=0.5,expectedReturn=0.008;
double maxParticipation=0.1;
for(double dollars:{100000.0,1000000.0,4000000.0}){
    double participation=dollars/averageDailyValue;
    double impact=impactCoefficient*volatility*sqrt(participation);
    bool permitted=participation<=maxParticipation;
    double net=expectedReturn-impact-0.0003;
    cout<<"Order "<<dollars<<" participation "<<participation
        <<" permitted "<<permitted<<" net "<<net<<endl;
}
    return 0;
}
